package fr.sary.radioprogrammee;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 final int BG=0xff09172b,CARD=0xff152a45,BLUE=0xff36b8ff,WHITE=0xfff4f8ff,MUTED=0xff9fb2ce; LinearLayout root,items,grid; TextView now,status; SeekBar volume; String[] names={"Chérie FM","RTL","RFM","Nostalgie","NRJ","France Inter","Personnalisée"}; String[] urls={"https://scdn.nrjaudio.fm/adwz1/fr/30201/mp3_128.mp3","https://streamer-02.rtl.fr/rtl-1-44-128","https://stream.rfm.fr/rfm.mp3","https://scdn.nrjaudio.fm/adwz1/fr/30601/mp3_128.mp3","https://scdn.nrjaudio.fm/adwz1/fr/30001/mp3_128.mp3","https://icecast.radiofrance.fr/franceinter-midfi.mp3",""}; int selected=0; String customUrl="";
 int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} GradientDrawable bg(int color,int rad){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(rad));return d;}
 TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 LinearLayout panel(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),dp(16),dp(16),dp(16));l.setBackground(bg(CARD,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,dp(10));root.addView(l,lp);return l;}
 void gap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
 void action(LinearLayout l,String title,Runnable r){TextView t=label(title,15,WHITE,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(12),dp(13),dp(12),dp(13));t.setBackground(bg(0xff22517c,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));l.addView(t,lp);t.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(18),dp(18),dp(24));scroll.addView(root);setContentView(scroll);
 root.addView(label("📻  RADIO PROGRAMMÉE",23,WHITE,true));root.addView(label("PREMIUM  •  V1.1",12,BLUE,true));gap(root,16);
 LinearLayout player=panel();player.addView(label("À L'ÉCOUTE",12,BLUE,true));gap(player,8);now=label("",24,WHITE,true);player.addView(now);status=label("Choisissez votre station",13,MUTED,false);player.addView(status);gap(player,14);action(player,"▶  ÉCOUTER",()->play());action(player,"■  ARRÊTER",()->{startService(new Intent(this,RadioService.class).setAction("STOP"));status.setText("Lecture arrêtée");});gap(player,10);player.addView(label("VOLUME",12,MUTED,true));volume=new SeekBar(this);android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int max=audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC);volume.setMax(max);volume.setProgress(audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){if(user)audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,v,0);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});player.addView(volume);
 root.addView(label("MES STATIONS",20,WHITE,true));root.addView(label("Touchez une station pour l'écouter",13,MUTED,false));grid=new LinearLayout(this);grid.setOrientation(1);root.addView(grid);selected=Schedule.prefs(this).getInt("station",0);if(selected<0||selected>=names.length)selected=0;customUrl=Schedule.prefs(this).getString("custom_url","");renderStations();
 LinearLayout schedule=panel();schedule.addView(label("⏰  PROGRAMMATIONS",19,WHITE,true));schedule.addView(label("Plusieurs créneaux par jour • horaires mémorisés",12,MUTED,false));items=new LinearLayout(this);items.setOrientation(1);schedule.addView(items);action(schedule,"＋  AJOUTER UNE PLAGE HORAIRE",()->edit(-1));render();}
 void renderStations(){grid.removeAllViews();for(int row=0;row<4;row++){LinearLayout line=new LinearLayout(this);line.setOrientation(0);grid.addView(line);for(int col=0;col<2;col++){int ix=row*2+col;if(ix>=names.length)continue;final int index=ix;LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(5),dp(16),dp(5),dp(16));GradientDrawable d=bg(ix==selected?0xff176096:CARD,16);if(ix==selected)d.setStroke(dp(2),BLUE);tile.setBackground(d);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(104),1);lp.setMargins(dp(4),dp(5),dp(4),dp(5));line.addView(tile,lp);String[] marks={"♥","RTL","RFM","♫","NRJ","FI","＋"};TextView logo=label(marks[ix],25,ix==selected?WHITE:BLUE,true);logo.setGravity(Gravity.CENTER);tile.addView(logo);TextView name=label(names[ix],13,WHITE,true);name.setGravity(Gravity.CENTER);tile.addView(name);tile.setOnClickListener(v->{if(index==6)askCustom();else{selected=index;Schedule.prefs(this).edit().putInt("station",index).putString("url",urls[index]).apply();renderStations();play();}});}}now.setText(names[selected]);}
 void askCustom(){EditText e=new EditText(this);e.setSingleLine();e.setInputType( android.text.InputType.TYPE_TEXT_VARIATION_URI);e.setText(customUrl);e.setHint("https://.../stream.mp3");new AlertDialog.Builder(this).setTitle("Flux radio personnalisé").setView(e).setNegativeButton("Annuler",null).setPositiveButton("Écouter",(d,w)->{String u=e.getText().toString().trim();if(!u.startsWith("http://")&&!u.startsWith("https://")){toast("Adresse HTTP(S) invalide");return;}customUrl=u;selected=6;Schedule.prefs(this).edit().putInt("station",6).putString("custom_url",u).putString("url",u).apply();renderStations();play();}).show();}
 void play(){String u=Schedule.prefs(this).getString("url",urls[0]);if(u.isEmpty()){askCustom();return;}startForegroundService(new Intent(this,RadioService.class).setAction("PLAY"));status.setText("Connexion à "+names[selected]+"…");now.setText(names[selected]);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}String fmt(int m){return String.format(Locale.FRANCE,"%02d:%02d",m/60,m%60);}
 void render(){items.removeAllViews();JSONArray a=Schedule.slots(this);for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);int index=i;action(items,"🕒 "+fmt(o.getInt("start"))+" → "+fmt(o.getInt("end"))+"   •   Modifier",()->edit(index));}catch(Exception ignored){}}
 void edit(int index){JSONArray a=Schedule.slots(this);JSONObject old=new JSONObject();try{if(index>=0)old=a.getJSONObject(index);}catch(Exception ignored){}final JSONObject prev=old;LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(22),0,dp(22),0);TextView hint=label("Début et fin (HH:MM), puis jours :",14,Color.DKGRAY,false);form.addView(hint);EditText start=new EditText(this),end=new EditText(this);start.setSingleLine();end.setSingleLine();start.setHint("07:00");end.setHint("09:00");start.setText(fmt(prev.optInt("start",420)));end.setText(fmt(prev.optInt("end",540)));form.addView(start);form.addView(end);String[] days={"Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi","Dimanche"};CheckBox[] checks=new CheckBox[7];for(int d=0;d<7;d++){checks[d]=new CheckBox(this);checks[d].setText(days[d]);checks[d].setChecked((prev.optInt("days",127)&(1<<d))!=0);form.addView(checks[d]);}AlertDialog.Builder dlg=new AlertDialog.Builder(this).setTitle(index<0?"Ajouter un horaire":"Modifier un horaire").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(di,w)->{try{int st=parse(start.getText().toString()),en=parse(end.getText().toString());int mask=0;for(int d=0;d<7;d++)if(checks[d].isChecked())mask|=1<<d;if(mask==0||st==en){toast("Choisir des jours et des heures différentes");return;}JSONObject obj=new JSONObject();obj.put("start",st);obj.put("end",en);obj.put("days",mask);JSONArray result=new JSONArray();for(int i=0;i<a.length();i++)result.put(i==index?obj:a.getJSONObject(i));if(index<0)result.put(obj);Schedule.save(this,result);render();}catch(Exception e){toast("Heure invalide : HH:MM");}});if(index>=0)dlg.setNeutralButton("Supprimer",(di,w)->{JSONArray result=new JSONArray();for(int i=0;i<a.length();i++)if(i!=index)try{result.put(a.getJSONObject(i));}catch(Exception ignored){}Schedule.save(this,result);render();});dlg.show();}
 int parse(String s){String[] p=s.trim().split(":");if(p.length!=2)throw new IllegalArgumentException();int h=Integer.parseInt(p[0]),m=Integer.parseInt(p[1]);if(h<0||h>23||m<0||m>59)throw new IllegalArgumentException();return h*60+m;}
}
